#include <string>
#include <vector>
#include <unordered_set>
#include <cstring>
#include <iomanip>
#include <sstream>

class Solution {
public:
    long long countGoodIntegersOnGridPath(long long l, long long r, std::string directions) {
        std::vector<int> pathIndices = {0};
        int cr = 0, cc = 0;
        for (char move : directions) {
            if (move == 'D') cr++;
            else cc++;
            pathIndices.push_back(cr * 4 + cc);
        }
        std::unordered_set<int> pathSet(pathIndices.begin(), pathIndices.end());

        auto countUpTo = [&](long long n) -> long long {
            if (n < 0) return 0;
            std::ostringstream oss;
            oss << std::setw(16) << std::setfill('0') << n;
            std::string s = oss.str();
            long long memo[17][2][10];
            std::memset(memo, -1, sizeof(memo));

            auto dp = [&](auto& self, int idx, bool isLess, int lastVal) -> long long {
                if (idx == 16) return 1;
                if (memo[idx][isLess][lastVal] != -1) return memo[idx][isLess][lastVal];
                int limit = isLess ? 9 : (s[idx] - '0');
                long long total = 0;
                bool isOnPath = pathSet.count(idx);
                int startDigit = isOnPath ? lastVal : 0;
                for (int d = startDigit; d <= limit; ++d) {
                    bool nxtLess = isLess || (d < limit);
                    int nxtLast = isOnPath ? d : lastVal;
                    total += self(self, idx + 1, nxtLess, nxtLast);
                }
                return memo[idx][isLess][lastVal] = total;
            };
            return dp(dp, 0, false, 0);
        };

        return countUpTo(r) - countUpTo(l - 1);
    }
};

import java.util.*;

class Solution {
    public long countGoodIntegersOnGridPath(long long l, long long r, String directions) {
        List<Integer> pathIndices = new ArrayList<>();
        pathIndices.add(0);
        int cr = 0, cc = 0;
        for (char move : directions.toCharArray()) {
            if (move == 'D') cr++;
            else cc++;
            pathIndices.add(cr * 4 + cc);
        }
        Set<Integer> pathSet = new HashSet<>(pathIndices);

        return countUpTo(r, pathSet) - countUpTo(l - 1, pathSet);
    }

    private long countUpTo(long n, Set<Integer> pathSet) {
        if (n < 0) return 0;
        String s = String.format("%016d", n);
        Long[][][] memo = new Long[17][2][10];
        return dp(0, false, 0, s, pathSet, memo);
    }

    private long dp(int idx, boolean isLess, int lastVal, String s, Set<Integer> pathSet, Long[][][] memo) {
        if (idx == 16) return 1;
        int lessIdx = isLess ? 1 : 0;
        if (memo[idx][lessIdx][lastVal] != null) return memo[idx][lessIdx][lastVal];
        int limit = isLess ? 9 : (s.charAt(idx) - '0');
        long total = 0;
        boolean isOnPath = pathSet.contains(idx);
        int startDigit = isOnPath ? lastVal : 0;
        for (int d = startDigit; d <= limit; d++) {
            boolean nxtLess = isLess || (d < limit);
            int nxtLast = isOnPath ? d : lastVal;
            total += dp(idx + 1, nxtLess, nxtLast, s, pathSet, memo);
        }
        return memo[idx][lessIdx][lastVal] = total;
    }
}

function countGoodIntegersOnGridPath(l, r, directions) {
    const pathIndices = [0];
    let cr = 0, cc = 0;
    for (const move of directions) {
        if (move === 'D') cr++;
        else cc++;
        pathIndices.push(cr * 4 + cc);
    }
    const pathSet = new Set(pathIndices);

    function countUpTo(n) {
        if (n < 0n) return 0n;
        const s = n.toString().padStart(16, '0');
        const memo = new Map();

        function dp(idx, isLess, lastVal) {
            if (idx === 16) return 1n;
            const key = `${idx},${isLess ? 1 : 0},${lastVal}`;
            if (memo.has(key)) return memo.get(key);
            const limit = isLess ? 9 : Number(s[idx]);
            let total = 0n;
            const isOnPath = pathSet.has(idx);
            const startDigit = isOnPath ? lastVal : 0;
            for (let d = startDigit; d <= limit; d++) {
                const nxtLess = isLess || (d < limit);
                const nxtLast = isOnPath ? d : lastVal;
                total += dp(idx + 1, nxtLess, nxtLast);
            }
            memo.set(key, total);
            return total;
        }
        return dp(0, false, 0);
    }

    return Number(countUpTo(BigInt(r)) - countUpTo(BigInt(l) - 1n));
}
